/* Stand-in for NSIS's makensis: answers CPack's version probe and records the
   script CPack asks it to compile, so the generated project.nsi can be read on
   a machine without NSIS. It builds no installer. */
#include <stdio.h>
#include <string.h>

int main(int argc, char **argv)
{
    for (int i = 1; i < argc; ++i) {
        if (_stricmp(argv[i], "/VERSION") == 0 || _stricmp(argv[i], "-VERSION") == 0) {
            printf("v3.10\n");
            return 0;
        }
    }
    FILE *log = fopen("C:\\b\\rpb-stub\\calls.txt", "a");
    if (log) {
        for (int i = 0; i < argc; ++i)
            fprintf(log, "%s%s", i ? " " : "", argv[i]);
        fprintf(log, "\n");
        fclose(log);
    }
    printf("makensis stand-in: no installer built\n");
    return 0;
}

